insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('ba1d4600-ca6b-5cda-9676-f754b7ba6912', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'baghdad', 'federal', 33.3152, 44.3661, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Baghdad","ar":"بغداد","ckb":"بەغدا","fr":"Bagdad","de":"Bagdad","es":"Bagdad"}'::jsonb, '{"en":"Baghdad","ar":"بغداد","ckb":"بەغدا"}'::jsonb, '{"en":"Iraq''s capital on the Tigris, home to the Iraq Museum, the book market of Al-Mutanabbi Street and Abbasid-era monuments.","ar":"عاصمة العراق على ضفاف دجلة، وفيها المتحف العراقي وسوق الكتب في شارع المتنبي ومعالم من العصر العباسي."}'::jsonb, '{"en":"Founded in 762 CE by the Abbasid caliph al-Mansur as the ''Round City'', Baghdad became one of the world''s great centres of learning during the Islamic Golden Age, home to the House of Wisdom.","ar":"أسسها الخليفة العباسي أبو جعفر المنصور عام 762م باسم «المدينة المدوّرة»، وغدت من أعظم مراكز العلم في العصر الذهبي الإسلامي حيث بيت الحكمة."}'::jsonb, '{"en":"Central Iraq, on both banks of the Tigris River in the Mesopotamian alluvial plain.","ar":"وسط العراق، على ضفتي نهر دجلة في السهل الرسوبي لبلاد الرافدين."}'::jsonb, '{"en":"October to April is generally the most comfortable period; summers (June–September) are extremely hot. Check religious calendars, as major pilgrimages affect crowds and prices.","ar":"تعدّ الفترة من تشرين الأول إلى نيسان الأنسب عموماً؛ أما الصيف (حزيران–أيلول) فشديد الحرارة. راجع التقويم الديني لأن مواسم الزيارات الكبرى تؤثر على الازدحام والأسعار."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('0377e504-cc2d-5112-9011-c9a08cee2c1a', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'basra', 'federal', 30.5085, 47.7804, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Basra","ar":"البصرة","ckb":"بەسرە","fr":"Bassorah","de":"Basra","es":"Basora"}'::jsonb, '{"en":"Basra","ar":"البصرة","ckb":"بەسرە"}'::jsonb, '{"en":"Iraq''s main port city on the Shatt al-Arab, known for its corniche, date palms and gateway to the Gulf.","ar":"المدينة الساحلية الرئيسية في العراق على شط العرب، تشتهر بكورنيشها ونخيلها وبوابتها نحو الخليج."}'::jsonb, '{"en":"Founded in the 7th century CE, Basra was an early Islamic centre of grammar, literature and trade, linked to the legends of Sindbad the Sailor.","ar":"تأسست في القرن السابع الميلادي، وكانت مركزاً إسلامياً مبكراً للنحو والأدب والتجارة، وارتبط اسمها بحكايات السندباد البحري."}'::jsonb, '{"en":"Far south-east of Iraq where the Tigris and Euphrates join as the Shatt al-Arab before reaching the Gulf.","ar":"أقصى جنوب شرق العراق حيث يلتقي دجلة والفرات في شط العرب قبل أن يصبّا في الخليج."}'::jsonb, '{"en":"October to April is generally the most comfortable period; summers (June–September) are extremely hot. Check religious calendars, as major pilgrimages affect crowds and prices.","ar":"تعدّ الفترة من تشرين الأول إلى نيسان الأنسب عموماً؛ أما الصيف (حزيران–أيلول) فشديد الحرارة. راجع التقويم الديني لأن مواسم الزيارات الكبرى تؤثر على الازدحام والأسعار."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('0197db69-38e3-54ef-88c9-3de576d6dac7', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'dhi-qar', 'federal', 31.0439, 46.2575, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Dhi Qar","ar":"ذي قار","ckb":"زیقار","fr":"Dhi Qar","de":"Dhi Qar","es":"Di Qar"}'::jsonb, '{"en":"Nasiriyah","ar":"الناصرية","ckb":"ناسریە"}'::jsonb, '{"en":"Heartland of ancient Sumer: the Ziggurat of Ur, Eridu, Lagash and Girsu, plus the reed villages of the southern marshes.","ar":"قلب سومر القديمة: زقورة أور وأريدو ولكش وجرسو، إضافة إلى قرى القصب في الأهوار الجنوبية."}'::jsonb, '{"en":"Sumerian city-states flourished here from the 4th millennium BCE. Ur was a major Sumerian capital, and Eridu is regarded in Mesopotamian tradition as one of the oldest cities.","ar":"ازدهرت هنا دويلات المدن السومرية منذ الألف الرابع قبل الميلاد، وكانت أور عاصمة سومرية كبرى، وتعدّ أريدو في التقليد الرافديني من أقدم المدن."}'::jsonb, '{"en":"Southern Iraq along the Euphrates, bordering the Central and Hammar marshes.","ar":"جنوب العراق على نهر الفرات، ومجاورة للأهوار الوسطى وهور الحمّار."}'::jsonb, '{"en":"October to April is generally the most comfortable period; summers (June–September) are extremely hot. Check religious calendars, as major pilgrimages affect crowds and prices.","ar":"تعدّ الفترة من تشرين الأول إلى نيسان الأنسب عموماً؛ أما الصيف (حزيران–أيلول) فشديد الحرارة. راجع التقويم الديني لأن مواسم الزيارات الكبرى تؤثر على الازدحام والأسعار."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('922118ac-16bd-562a-a76b-8b70c8fa72d2', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'maysan', 'federal', 31.8356, 47.144, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Maysan","ar":"ميسان","ckb":"مەیسان"}'::jsonb, '{"en":"Amarah","ar":"العمارة","ckb":"عەمارە"}'::jsonb, '{"en":"A Tigris governorate that includes parts of the Huwaizah and Central marshes and a long tradition of Marsh Arab culture.","ar":"محافظة على نهر دجلة تضم أجزاء من هور الحويزة والأهوار الوسطى وتقاليد عريقة لعرب الأهوار."}'::jsonb, '{"en":"The region has been inhabited since antiquity; the marsh communities here preserve reed-house building and water-buffalo herding traditions.","ar":"سكنت المنطقة منذ القدم، وتحافظ مجتمعات الأهوار فيها على تقاليد بناء بيوت القصب وتربية الجاموس."}'::jsonb, '{"en":"South-eastern Iraq along the Tigris, bordering Iran.","ar":"جنوب شرق العراق على نهر دجلة ومحاذية لإيران."}'::jsonb, '{"en":"October to April is generally the most comfortable period; summers (June–September) are extremely hot. Check religious calendars, as major pilgrimages affect crowds and prices.","ar":"تعدّ الفترة من تشرين الأول إلى نيسان الأنسب عموماً؛ أما الصيف (حزيران–أيلول) فشديد الحرارة. راجع التقويم الديني لأن مواسم الزيارات الكبرى تؤثر على الازدحام والأسعار."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('bc041521-0cc8-5b77-87ef-544de264c19f', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'najaf', 'federal', 31.9961, 44.3143, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Najaf","ar":"النجف","ckb":"نەجەف","fr":"Nadjaf","de":"Nadschaf","es":"Náyaf"}'::jsonb, '{"en":"Najaf","ar":"النجف","ckb":"نەجەف"}'::jsonb, '{"en":"One of the holiest cities in Shia Islam, home to the Imam Ali Shrine and the vast Wadi al-Salam cemetery; nearby Kufa holds its historic mosque.","ar":"من أقدس المدن لدى المسلمين الشيعة، وفيها مرقد الإمام علي ومقبرة وادي السلام، وبالقرب منها الكوفة ومسجدها التاريخي."}'::jsonb, '{"en":"Najaf grew around the shrine of Imam Ali ibn Abi Talib and has been a major centre of Islamic scholarship (the Hawza) for centuries.","ar":"نشأت النجف حول مرقد الإمام علي بن أبي طالب، وكانت لقرون مركزاً كبيراً للعلوم الإسلامية (الحوزة)."}'::jsonb, '{"en":"South-central Iraq on the edge of the Western Desert, near the Euphrates.","ar":"جنوب وسط العراق على حافة الصحراء الغربية قرب نهر الفرات."}'::jsonb, '{"en":"October to April is generally the most comfortable period; summers (June–September) are extremely hot. Check religious calendars, as major pilgrimages affect crowds and prices.","ar":"تعدّ الفترة من تشرين الأول إلى نيسان الأنسب عموماً؛ أما الصيف (حزيران–أيلول) فشديد الحرارة. راجع التقويم الديني لأن مواسم الزيارات الكبرى تؤثر على الازدحام والأسعار."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('743750bf-c400-5645-94bc-4e3306ab7c0d', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'karbala', 'federal', 32.616, 44.0249, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Karbala","ar":"كربلاء","ckb":"کەربەلا","fr":"Kerbala","de":"Kerbela","es":"Kerbala"}'::jsonb, '{"en":"Karbala","ar":"كربلاء","ckb":"کەربەلا"}'::jsonb, '{"en":"A major pilgrimage city with the shrines of Imam Hussein and Al-Abbas; the desert fortress of Al-Ukhaidir and Lake Razzaza lie to the west.","ar":"مدينة زيارة كبرى فيها مرقدا الإمام الحسين وأبي الفضل العباس، وإلى غربها حصن الأخيضر وبحيرة الرزازة."}'::jsonb, '{"en":"Karbala is the site of the Battle of Karbala (680 CE). Annual commemorations such as Ashura and Arbaeen draw very large numbers of pilgrims.","ar":"شهدت كربلاء واقعة الطف عام 680م، وتستقطب ذكرى عاشوراء والأربعين أعداداً هائلة من الزائرين سنوياً."}'::jsonb, '{"en":"Central Iraq, west of the Euphrates on the edge of the desert.","ar":"وسط العراق، غرب الفرات على حافة الصحراء."}'::jsonb, '{"en":"October to April is generally the most comfortable period; summers (June–September) are extremely hot. Check religious calendars, as major pilgrimages affect crowds and prices.","ar":"تعدّ الفترة من تشرين الأول إلى نيسان الأنسب عموماً؛ أما الصيف (حزيران–أيلول) فشديد الحرارة. راجع التقويم الديني لأن مواسم الزيارات الكبرى تؤثر على الازدحام والأسعار."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('e260f45a-82f7-5224-8357-2e4e7016202c', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'babylon', 'federal', 32.4637, 44.4196, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Babylon","ar":"بابل","ckb":"بابل","fr":"Babylone","de":"Babylon","es":"Babilonia"}'::jsonb, '{"en":"Hillah","ar":"الحلة","ckb":"حیللە"}'::jsonb, '{"en":"Home to the ruins of ancient Babylon, a UNESCO World Heritage Site, with the Lion of Babylon and the Processional Way.","ar":"موطن أطلال بابل القديمة المدرجة على قائمة التراث العالمي، وفيها أسد بابل وشارع الموكب."}'::jsonb, '{"en":"Babylon rose to prominence under Hammurabi (18th century BCE) and again under Nebuchadnezzar II (6th century BCE), when the Ishtar Gate and Processional Way were built.","ar":"برزت بابل في عهد حمورابي (القرن الثامن عشر ق.م) ثم في عهد نبوخذنصر الثاني (القرن السادس ق.م) حين شُيّدت بوابة عشتار وشارع الموكب."}'::jsonb, '{"en":"Central Iraq on the Euphrates (Shatt al-Hillah), south of Baghdad.","ar":"وسط العراق على نهر الفرات (شط الحلة) جنوب بغداد."}'::jsonb, '{"en":"October to April is generally the most comfortable period; summers (June–September) are extremely hot. Check religious calendars, as major pilgrimages affect crowds and prices.","ar":"تعدّ الفترة من تشرين الأول إلى نيسان الأنسب عموماً؛ أما الصيف (حزيران–أيلول) فشديد الحرارة. راجع التقويم الديني لأن مواسم الزيارات الكبرى تؤثر على الازدحام والأسعار."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('6c7bfd2f-96d5-5791-898b-0ccb5905cb89', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'wasit', 'federal', 32.5128, 45.8182, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Wasit","ar":"واسط","ckb":"واست"}'::jsonb, '{"en":"Kut","ar":"الكوت","ckb":"کووت"}'::jsonb, '{"en":"A Tigris governorate named after the early Islamic city of Wasit, with the Kut Barrage and agricultural landscapes.","ar":"محافظة على نهر دجلة سُمّيت نسبة إلى مدينة واسط الإسلامية المبكرة، وفيها سدة الكوت ومناظر زراعية."}'::jsonb, '{"en":"The city of Wasit was founded around 702 CE by al-Hajjaj ibn Yusuf as a garrison town midway between Kufa and Basra.","ar":"أسس الحجاج بن يوسف مدينة واسط نحو عام 702م معسكراً في منتصف الطريق بين الكوفة والبصرة."}'::jsonb, '{"en":"Eastern-central Iraq on the Tigris, bordering Iran.","ar":"شرق وسط العراق على نهر دجلة ومحاذية لإيران."}'::jsonb, '{"en":"October to April is generally the most comfortable period; summers (June–September) are extremely hot. Check religious calendars, as major pilgrimages affect crowds and prices.","ar":"تعدّ الفترة من تشرين الأول إلى نيسان الأنسب عموماً؛ أما الصيف (حزيران–أيلول) فشديد الحرارة. راجع التقويم الديني لأن مواسم الزيارات الكبرى تؤثر على الازدحام والأسعار."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('0a3822c2-c34e-56d0-8de6-09264ee19ed8', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'qadisiyah', 'federal', 31.9929, 44.9255, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Qadisiyah","ar":"القادسية","ckb":"قادسیە"}'::jsonb, '{"en":"Diwaniyah","ar":"الديوانية","ckb":"دیوانیە"}'::jsonb, '{"en":"An agricultural governorate on the Euphrates that contains the ancient Sumerian religious centre of Nippur.","ar":"محافظة زراعية على الفرات تضم مدينة نفّر السومرية الدينية القديمة."}'::jsonb, '{"en":"Nippur was the seat of the god Enlil and one of the most important religious centres of ancient Mesopotamia.","ar":"كانت نفّر مقرّ الإله إنليل ومن أهم المراكز الدينية في بلاد الرافدين القديمة."}'::jsonb, '{"en":"South-central Iraq on the Euphrates plain.","ar":"جنوب وسط العراق في سهل الفرات."}'::jsonb, '{"en":"October to April is generally the most comfortable period; summers (June–September) are extremely hot. Check religious calendars, as major pilgrimages affect crowds and prices.","ar":"تعدّ الفترة من تشرين الأول إلى نيسان الأنسب عموماً؛ أما الصيف (حزيران–أيلول) فشديد الحرارة. راجع التقويم الديني لأن مواسم الزيارات الكبرى تؤثر على الازدحام والأسعار."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('6655e779-48c0-530f-a6c6-9795b6c7e687', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'muthanna', 'federal', 31.3099, 45.2806, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Muthanna","ar":"المثنى","ckb":"موسەننا"}'::jsonb, '{"en":"Samawah","ar":"السماوة","ckb":"سەماوە"}'::jsonb, '{"en":"Contains Uruk (Warka), one of the world''s earliest cities and part of the UNESCO-listed Ahwar of Southern Iraq.","ar":"تضم الوركاء (أوروك)، من أقدم مدن العالم وجزء من موقع الأهوار المدرج في اليونسكو."}'::jsonb, '{"en":"Uruk is associated with the early development of writing and monumental architecture in the 4th millennium BCE and with the Epic of Gilgamesh.","ar":"ارتبطت أوروك بنشوء الكتابة والعمارة الضخمة في الألف الرابع قبل الميلاد وبملحمة جلجامش."}'::jsonb, '{"en":"Southern Iraq; largely desert extending to the Saudi border, with the Euphrates in the north.","ar":"جنوب العراق، معظمها صحراء تمتد حتى الحدود السعودية والفرات في شمالها."}'::jsonb, '{"en":"October to April is generally the most comfortable period; summers (June–September) are extremely hot. Check religious calendars, as major pilgrimages affect crowds and prices.","ar":"تعدّ الفترة من تشرين الأول إلى نيسان الأنسب عموماً؛ أما الصيف (حزيران–أيلول) فشديد الحرارة. راجع التقويم الديني لأن مواسم الزيارات الكبرى تؤثر على الازدحام والأسعار."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('f9b0373f-7e11-554d-8f9d-2b033243f3a5', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'anbar', 'federal', 33.4206, 43.3078, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Anbar","ar":"الأنبار","ckb":"ئەنبار"}'::jsonb, '{"en":"Ramadi","ar":"الرمادي","ckb":"ڕومادی"}'::jsonb, '{"en":"Iraq''s largest governorate by area, covering the Euphrates valley and the Western Desert, with Lake Habbaniyah and historic river towns.","ar":"أكبر محافظات العراق مساحة، تشمل وادي الفرات والصحراء الغربية وبحيرة الحبانية والمدن النهرية التاريخية."}'::jsonb, '{"en":"The Euphrates corridor has been a trade route since antiquity, with towns such as Hit and Anah and traditional water wheels (na''oor).","ar":"كان ممر الفرات طريقاً تجارياً منذ القدم، وفيه مدن مثل هيت وعنة والنواعير التقليدية."}'::jsonb, '{"en":"Western Iraq, bordering Syria, Jordan and Saudi Arabia.","ar":"غرب العراق، محاذية لسوريا والأردن والسعودية."}'::jsonb, '{"en":"October to April is generally the most comfortable period; summers (June–September) are extremely hot. Check religious calendars, as major pilgrimages affect crowds and prices.","ar":"تعدّ الفترة من تشرين الأول إلى نيسان الأنسب عموماً؛ أما الصيف (حزيران–أيلول) فشديد الحرارة. راجع التقويم الديني لأن مواسم الزيارات الكبرى تؤثر على الازدحام والأسعار."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('6b4ff7c3-31c9-5231-9fca-ce6770993f39', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'diyala', 'federal', 33.7466, 44.6437, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Diyala","ar":"ديالى","ckb":"دیالە"}'::jsonb, '{"en":"Baqubah","ar":"بعقوبة","ckb":"بەعقووبە"}'::jsonb, '{"en":"Known for orchards and orange groves along the Diyala River, stretching from the Baghdad plain to the Hamrin hills.","ar":"تشتهر بالبساتين وأشجار البرتقال على نهر ديالى، وتمتد من سهل بغداد إلى تلال حمرين."}'::jsonb, '{"en":"The Diyala valley contains numerous ancient tells, including sites excavated in the 20th century that shed light on early Mesopotamian cities.","ar":"يضم وادي ديالى تلالاً أثرية كثيرة نُقّب بعضها في القرن العشرين وكشفت عن مدن رافدينية مبكرة."}'::jsonb, '{"en":"Eastern Iraq along the Diyala River, bordering Iran.","ar":"شرق العراق على نهر ديالى ومحاذية لإيران."}'::jsonb, '{"en":"October to April is generally the most comfortable period; summers (June–September) are extremely hot. Check religious calendars, as major pilgrimages affect crowds and prices.","ar":"تعدّ الفترة من تشرين الأول إلى نيسان الأنسب عموماً؛ أما الصيف (حزيران–أيلول) فشديد الحرارة. راجع التقويم الديني لأن مواسم الزيارات الكبرى تؤثر على الازدحام والأسعار."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('03793466-c810-5844-8e51-b11a3c9094ec', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'salah-al-din', 'federal', 34.6071, 43.6782, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Salah al-Din","ar":"صلاح الدين","ckb":"سەلاحەدین"}'::jsonb, '{"en":"Tikrit","ar":"تكريت","ckb":"تکریت"}'::jsonb, '{"en":"Contains two UNESCO World Heritage Sites: the Abbasid capital of Samarra with its spiral Malwiya Minaret, and ancient Ashur.","ar":"تضم موقعين للتراث العالمي: سامراء العاصمة العباسية ومئذنتها الملوية، ومدينة آشور القديمة."}'::jsonb, '{"en":"Samarra served as the Abbasid capital in the 9th century CE. Ashur was the first capital and religious centre of the Assyrian state.","ar":"كانت سامراء عاصمة للعباسيين في القرن التاسع الميلادي، وكانت آشور العاصمة الأولى والمركز الديني للدولة الآشورية."}'::jsonb, '{"en":"North-central Iraq along the Tigris.","ar":"شمال وسط العراق على نهر دجلة."}'::jsonb, '{"en":"October to April is generally the most comfortable period; summers (June–September) are extremely hot. Check religious calendars, as major pilgrimages affect crowds and prices.","ar":"تعدّ الفترة من تشرين الأول إلى نيسان الأنسب عموماً؛ أما الصيف (حزيران–أيلول) فشديد الحرارة. راجع التقويم الديني لأن مواسم الزيارات الكبرى تؤثر على الازدحام والأسعار."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('8b5f9dd4-3402-5aaa-9cc2-8a58611e7112', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'nineveh', 'federal', 36.335, 43.1189, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Nineveh","ar":"نينوى","ckb":"نەینەوا","fr":"Ninive","de":"Ninive","es":"Nínive"}'::jsonb, '{"en":"Mosul","ar":"الموصل","ckb":"مووسڵ"}'::jsonb, '{"en":"Northern governorate with Mosul''s old city and the Assyrian capitals of Nineveh and Nimrud, plus the Parthian-era city of Hatra.","ar":"محافظة شمالية تضم الموصل القديمة والعاصمتين الآشوريتين نينوى ونمرود، ومدينة الحضر من العهد الفرثي."}'::jsonb, '{"en":"Nineveh was the capital of the Neo-Assyrian Empire under Sennacherib. Many heritage sites in the governorate were damaged between 2014 and 2017 and are subject to ongoing restoration.","ar":"كانت نينوى عاصمة الإمبراطورية الآشورية الحديثة في عهد سنحاريب. تعرّضت مواقع تراثية كثيرة في المحافظة للتدمير بين 2014 و2017 وتخضع لأعمال ترميم مستمرة."}'::jsonb, '{"en":"North-western Iraq on the Tigris, bordering Syria.","ar":"شمال غرب العراق على نهر دجلة ومحاذية لسوريا."}'::jsonb, '{"en":"Spring (March–May) and autumn (September–November) are pleasant; summers are hot in the lowlands but milder in the mountains, and winters can bring snow at altitude.","ar":"الربيع (آذار–أيار) والخريف (أيلول–تشرين الثاني) معتدلان؛ الصيف حار في السهول وألطف في الجبال، وقد يتساقط الثلج شتاءً في المرتفعات."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('2e3ab8fe-1de7-5b44-93c9-ea0a46a0c15c', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'kirkuk', 'federal', 35.4681, 44.3922, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Kirkuk","ar":"كركوك","ckb":"کەرکووک"}'::jsonb, '{"en":"Kirkuk","ar":"كركوك","ckb":"کەرکووک"}'::jsonb, '{"en":"A diverse city of Kurdish, Arab, Turkmen and Assyrian communities, centred on its historic citadel mound.","ar":"مدينة متنوعة تضم الكرد والعرب والتركمان والآشوريين، يتوسطها تلّ قلعتها التاريخية."}'::jsonb, '{"en":"The citadel mound has been occupied for thousands of years; the region is also known for the ''eternal fires'' of Baba Gurgur natural gas seeps.","ar":"سُكن تل القلعة منذ آلاف السنين، وتعرف المنطقة أيضاً بـ«النار الأزلية» في بابا كركر."}'::jsonb, '{"en":"Northern Iraq, between the Zagros foothills and the Tigris plain.","ar":"شمال العراق بين سفوح زاغروس وسهل دجلة."}'::jsonb, '{"en":"Spring (March–May) and autumn (September–November) are pleasant; summers are hot in the lowlands but milder in the mountains, and winters can bring snow at altitude.","ar":"الربيع (آذار–أيار) والخريف (أيلول–تشرين الثاني) معتدلان؛ الصيف حار في السهول وألطف في الجبال، وقد يتساقط الثلج شتاءً في المرتفعات."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('dd6319b9-a963-5cf3-bdfe-4935bf5171db', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'erbil', 'kurdistan_region', 36.1911, 44.0094, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Erbil","ar":"أربيل","ckb":"هەولێر","fr":"Erbil","de":"Erbil","es":"Erbil"}'::jsonb, '{"en":"Erbil (Hewlêr)","ar":"أربيل","ckb":"هەولێر"}'::jsonb, '{"en":"Capital of the Kurdistan Region, crowned by the UNESCO-listed Erbil Citadel, with bazaars, parks and mountain routes nearby.","ar":"عاصمة إقليم كردستان، تتوّجها قلعة أربيل المدرجة في اليونسكو، مع الأسواق والحدائق والطرق الجبلية القريبة."}'::jsonb, '{"en":"Erbil (ancient Arbela) is often cited as one of the longest continuously inhabited settlements; its citadel mound dates back millennia.","ar":"تُذكر أربيل (أربائيلو القديمة) كثيراً بين أقدم المستوطنات المأهولة باستمرار، ويعود تل قلعتها إلى آلاف السنين."}'::jsonb, '{"en":"Northern Iraq in the Kurdistan Region, between the Great and Little Zab rivers.","ar":"شمال العراق في إقليم كردستان، بين نهري الزاب الكبير والصغير."}'::jsonb, '{"en":"Spring (March–May) and autumn (September–November) are pleasant; summers are hot in the lowlands but milder in the mountains, and winters can bring snow at altitude.","ar":"الربيع (آذار–أيار) والخريف (أيلول–تشرين الثاني) معتدلان؛ الصيف حار في السهول وألطف في الجبال، وقد يتساقط الثلج شتاءً في المرتفعات."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('5fb82d98-8dc3-5106-96fe-be9cedf16bce', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'sulaymaniyah', 'kurdistan_region', 35.5613, 45.4373, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Sulaymaniyah","ar":"السليمانية","ckb":"سلێمانی","fr":"Souleimaniye","de":"Sulaimaniyya","es":"Solimania"}'::jsonb, '{"en":"Sulaymaniyah (Slêmanî)","ar":"السليمانية","ckb":"سلێمانی"}'::jsonb, '{"en":"A cultural centre of the Kurdistan Region surrounded by mountains, with the Sulaymaniyah Museum, Lake Dukan and the Ahmad Awa waterfall.","ar":"مركز ثقافي في إقليم كردستان تحيط به الجبال، وفيه متحف السليمانية وبحيرة دوكان وشلال أحمد آوا."}'::jsonb, '{"en":"Founded in 1784 by the Baban dynasty, Sulaymaniyah became an important centre of Kurdish literature and culture.","ar":"أسستها الإمارة البابانية عام 1784، وأصبحت مركزاً مهماً للأدب والثقافة الكردية."}'::jsonb, '{"en":"North-eastern Iraq in the Zagros mountains, bordering Iran.","ar":"شمال شرق العراق في جبال زاغروس ومحاذية لإيران."}'::jsonb, '{"en":"Spring (March–May) and autumn (September–November) are pleasant; summers are hot in the lowlands but milder in the mountains, and winters can bring snow at altitude.","ar":"الربيع (آذار–أيار) والخريف (أيلول–تشرين الثاني) معتدلان؛ الصيف حار في السهول وألطف في الجبال، وقد يتساقط الثلج شتاءً في المرتفعات."}'::jsonb, false) on conflict (id) do nothing;
insert into public.governorates (id, created_at, updated_at, published, slug, region, lat, lng, images, verification_status, last_verified, source_ids, name, capital, summary, history, geography, best_time_to_visit, is_demo) values ('9658bce8-6122-589a-a7c9-030c863c62d2', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'duhok', 'kurdistan_region', 36.8669, 42.9503, '[]'::jsonb, 'unverified', null, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', '{"en":"Duhok","ar":"دهوك","ckb":"دهۆک","fr":"Dohuk","de":"Dohuk","es":"Duhok"}'::jsonb, '{"en":"Duhok","ar":"دهوك","ckb":"دهۆک"}'::jsonb, '{"en":"Mountain governorate with the clifftop town of Amedi, the Yazidi holy valley of Lalish and the Sarsang resort area.","ar":"محافظة جبلية تضم بلدة العمادية على قمة جبل، ووادي لالش المقدس لدى الإيزيديين، ومنطقة سرسنك السياحية."}'::jsonb, '{"en":"The region has been home to Kurdish, Assyrian, Chaldean and Yazidi communities, with monasteries, rock reliefs and ancient routes.","ar":"سكنتها مجتمعات كردية وآشورية وكلدانية وإيزيدية، وفيها أديرة ونقوش صخرية وطرق قديمة."}'::jsonb, '{"en":"Far northern Iraq, bordering Turkey and Syria, with valleys and high mountain ranges.","ar":"أقصى شمال العراق، محاذية لتركيا وسوريا، بأودية وسلاسل جبلية عالية."}'::jsonb, '{"en":"Spring (March–May) and autumn (September–November) are pleasant; summers are hot in the lowlands but milder in the mountains, and winters can bring snow at altitude.","ar":"الربيع (آذار–أيار) والخريف (أيلول–تشرين الثاني) معتدلان؛ الصيف حار في السهول وألطف في الجبال، وقد يتساقط الثلج شتاءً في المرتفعات."}'::jsonb, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('16bbbf7f-90a4-5069-a37c-b75b23048bc1', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'iraq-museum', 'ba1d4600-ca6b-5cda-9676-f754b7ba6912', '{"en":"The Iraq Museum (National Museum of Iraq)","ar":"المتحف العراقي","ckb":"مۆزەخانەی عێراق","fr":"Musée national d''Irak","de":"Irakisches Nationalmuseum","es":"Museo Nacional de Irak"}'::jsonb, '{"museum"}', '{"history","archaeology","culture"}', '{"en":"Iraq''s principal museum, holding Sumerian, Babylonian, Assyrian and Islamic-era collections.","ar":"أهم متاحف العراق، ويضم مجموعات سومرية وبابلية وآشورية وإسلامية."}'::jsonb, '{"en":"Established in the 1920s, the museum was looted in 2003; thousands of objects have since been recovered and galleries progressively reopened.","ar":"تأسس في عشرينيات القرن العشرين وتعرّض للنهب عام 2003، واستُعيدت منذ ذلك الحين آلاف القطع وأعيد افتتاح القاعات تدريجياً."}'::jsonb, 33.3283, 44.387, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 3, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, true, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('710367f2-55ed-5860-9bb3-8f76e298cef8', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'al-mutanabbi-street', 'ba1d4600-ca6b-5cda-9676-f754b7ba6912', '{"en":"Al-Mutanabbi Street","ar":"شارع المتنبي","ckb":"شەقامی موتەنەبی","fr":"Rue al-Moutanabbi","de":"Al-Mutanabbi-Straße","es":"Calle Al-Mutanabbi"}'::jsonb, '{"market","cultural"}', '{"culture","history"}', '{"en":"Baghdad''s historic book market, busiest on Fridays, ending at the Shabandar Café and the Qishla.","ar":"سوق الكتب التاريخي في بغداد، يزدحم أيام الجمعة وينتهي عند مقهى الشابندر والقشلة."}'::jsonb, '{"en":"Named after the 10th-century poet al-Mutanabbi, the street has long been the heart of Baghdad''s literary life. It was rebuilt after a 2007 bombing.","ar":"سُمّي باسم الشاعر المتنبي (القرن العاشر)، وظل قلب الحياة الأدبية في بغداد، وأعيد بناؤه بعد تفجير عام 2007."}'::jsonb, 33.3398, 44.3853, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 2, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('d0eab50c-5187-5d72-a26d-95e0a3b5890a', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'abbasid-palace', 'ba1d4600-ca6b-5cda-9676-f754b7ba6912', '{"en":"Abbasid Palace","ar":"القصر العباسي","ckb":"کۆشکی عەباسی","fr":"Palais abbasside","de":"Abbasidenpalast","es":"Palacio abasí"}'::jsonb, '{"historic_city","archaeological"}', '{"history","archaeology"}', '{"en":"A brick building on the Tigris with fine muqarnas and arched iwans, from the late Abbasid period.","ar":"مبنى من الطابوق على ضفة دجلة بمقرنصات وأواوين جميلة من أواخر العصر العباسي."}'::jsonb, '{"en":"Dated to the late 12th–13th century; scholars debate whether it was a palace or a madrasa.","ar":"يُؤرّخ إلى أواخر القرن الثاني عشر أو الثالث عشر، ويختلف الباحثون حول كونه قصراً أم مدرسة."}'::jsonb, 33.3429, 44.3858, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 1, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('7cd353ae-269f-5a94-9cc5-7fcab99a764c', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'mustansiriya-madrasa', 'ba1d4600-ca6b-5cda-9676-f754b7ba6912', '{"en":"Al-Mustansiriya Madrasa","ar":"المدرسة المستنصرية","ckb":"قوتابخانەی موستەنسیریە","fr":"Madrasa al-Mustansiriya","de":"Mustansiriya-Madrasa","es":"Madrasa al-Mustansiriya"}'::jsonb, '{"historic_city"}', '{"history","culture"}', '{"en":"One of the oldest surviving institutions of higher learning in the Islamic world, on the Tigris near Souq al-Saray.","ar":"من أقدم مؤسسات التعليم العالي الباقية في العالم الإسلامي، على ضفة دجلة قرب سوق السراي."}'::jsonb, '{"en":"Founded in 1227–1234 CE by the Abbasid caliph al-Mustansir, it taught the four Sunni schools of law alongside medicine and other sciences.","ar":"أسسها الخليفة العباسي المستنصر بالله بين 1227 و1234م، ودُرّست فيها المذاهب الأربعة والطب وعلوم أخرى."}'::jsonb, 33.3415, 44.3888, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 1, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('f0ebe464-6643-52e2-8099-a180aacb2b1a', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'taq-kasra', 'ba1d4600-ca6b-5cda-9676-f754b7ba6912', '{"en":"Taq Kasra (Arch of Ctesiphon)","ar":"طاق كسرى","ckb":"تاقی کیسرا","fr":"Arc de Ctésiphon","de":"Taq-e Kisra","es":"Arco de Ctesifonte"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"The great brick arch of the Sasanian palace at Ctesiphon, near Salman Pak south-east of Baghdad.","ar":"القوس الطابوقي العظيم للقصر الساساني في المدائن قرب سلمان باك جنوب شرق بغداد."}'::jsonb, '{"en":"Built around the 6th century CE, it is among the largest single-span unreinforced brick vaults ever constructed. Restoration work has been carried out in recent years.","ar":"بُني نحو القرن السادس الميلادي، ويعدّ من أكبر الأقواس الطابوقية ذات الفتحة الواحدة في التاريخ، وجرت عليه أعمال ترميم في السنوات الأخيرة."}'::jsonb, 33.0937, 44.5807, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 1.5, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('2d1ac70a-4637-59c4-b1fd-9826a158cc7c', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'ziggurat-of-ur', '0197db69-38e3-54ef-88c9-3de576d6dac7', '{"en":"Ziggurat of Ur","ar":"زقورة أور","ckb":"زیگوراتی ئور","fr":"Ziggourat d''Ur","de":"Zikkurat von Ur","es":"Zigurat de Ur"}'::jsonb, '{"archaeological"}', '{"archaeology","history","religious"}', '{"en":"The best-preserved ziggurat in southern Mesopotamia, built for the moon god Nanna.","ar":"أفضل الزقورات حفظاً في جنوب بلاد الرافدين، شُيّدت لإله القمر نانا."}'::jsonb, '{"en":"Built under Ur-Nammu of the Third Dynasty of Ur around the 21st century BCE, its lower stages were partly reconstructed in the 20th century.","ar":"بناها أور-نمو من سلالة أور الثالثة نحو القرن الحادي والعشرين قبل الميلاد، وأعيد بناء أجزاء من طبقاتها السفلى في القرن العشرين."}'::jsonb, 30.9627, 46.1031, true, '{"listing":"The Ahwar of Southern Iraq: Refuge of Biodiversity and the Relict Landscape of the Mesopotamian Cities","year":2016,"url":"https://whc.unesco.org/en/list/1481"}'::jsonb, '[]'::jsonb, null, null, null, null, 'unknown', 2, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, true, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('bbf27582-2b05-57f4-bde4-875e68962b3c', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'ur', '0197db69-38e3-54ef-88c9-3de576d6dac7', '{"en":"Ancient City of Ur","ar":"مدينة أور الأثرية","ckb":"شاری کۆنی ئور","fr":"Cité antique d''Ur","de":"Antike Stadt Ur","es":"Antigua ciudad de Ur"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"Remains of one of Sumer''s greatest cities, including residential quarters and temples around the ziggurat.","ar":"بقايا إحدى أعظم مدن سومر، ومنها أحياء سكنية ومعابد حول الزقورة."}'::jsonb, '{"en":"Excavated by Leonard Woolley in the 1920s–30s; part of the UNESCO-inscribed Ahwar of Southern Iraq property.","ar":"نقّب فيها ليونارد وولي في عشرينيات وثلاثينيات القرن العشرين، وهي جزء من موقع الأهوار المدرج في اليونسكو."}'::jsonb, 30.9617, 46.103, true, '{"listing":"The Ahwar of Southern Iraq: Refuge of Biodiversity and the Relict Landscape of the Mesopotamian Cities","year":2016,"url":"https://whc.unesco.org/en/list/1481"}'::jsonb, '[]'::jsonb, null, null, null, null, 'unknown', 2, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, true, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('ef56fe29-c2ce-56c3-a4f5-0a0563aaa75b', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'royal-cemetery-of-ur', '0197db69-38e3-54ef-88c9-3de576d6dac7', '{"en":"Royal Cemetery of Ur","ar":"المقبرة الملكية في أور","ckb":"گۆڕستانی شاهانەی ئور","fr":"Cimetière royal d''Ur","de":"Königsfriedhof von Ur","es":"Cementerio real de Ur"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"Burial ground where some of the richest finds of Sumerian art were excavated, such as the ''Standard of Ur''.","ar":"مقبرة اكتُشفت فيها أغنى اللقى الفنية السومرية مثل «راية أور»."}'::jsonb, '{"en":"Dating to the mid-3rd millennium BCE; most objects are now in museums, and the visible remains are excavated pits and tombs.","ar":"تعود إلى منتصف الألف الثالث قبل الميلاد، ومعظم لقاها اليوم في المتاحف، وما يُرى منها حفر وقبور منقّبة."}'::jsonb, 30.961, 46.105, true, '{"listing":"The Ahwar of Southern Iraq: Refuge of Biodiversity and the Relict Landscape of the Mesopotamian Cities","year":2016,"url":"https://whc.unesco.org/en/list/1481"}'::jsonb, '[]'::jsonb, null, null, null, null, 'unknown', 1, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('046b533e-32fe-5734-8dce-99925e6a44bc', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'eridu', '0197db69-38e3-54ef-88c9-3de576d6dac7', '{"en":"Tell Eridu","ar":"تل أبو شهرين (أريدو)","ckb":"گردی ئەریدو","fr":"Eridu","de":"Eridu","es":"Eridu"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"Desert mound of Eridu, regarded in Sumerian tradition as the first city.","ar":"تلّ أريدو في الصحراء، وتعدّها التقاليد السومرية أول مدينة."}'::jsonb, '{"en":"Its temple sequence spans thousands of years of Mesopotamian religious architecture. The site is remote; access usually requires a local guide and permission.","ar":"تمتد سلسلة معابدها آلاف السنين من العمارة الدينية الرافدينية. الموقع نائي ويتطلب عادة دليلاً محلياً وموافقة."}'::jsonb, 30.8159, 45.9961, true, '{"listing":"The Ahwar of Southern Iraq: Refuge of Biodiversity and the Relict Landscape of the Mesopotamian Cities","year":2016,"url":"https://whc.unesco.org/en/list/1481"}'::jsonb, '[]'::jsonb, null, null, 'Remote desert site. Access arrangements not confirmed — check with local antiquities authorities.', null, 'unknown', 1, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('e9b54991-e7e1-54d7-8ff2-de3544d602ff', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'lagash', '0197db69-38e3-54ef-88c9-3de576d6dac7', '{"en":"Lagash (Al-Hiba)","ar":"لكش (تل الهبة)","ckb":"لەگەش","fr":"Lagash","de":"Lagasch","es":"Lagash"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"One of the largest Sumerian city-states, the subject of ongoing international excavations.","ar":"من أكبر دويلات المدن السومرية، وتجري فيها تنقيبات دولية مستمرة."}'::jsonb, '{"en":"Lagash rivalled Umma and Ur in the 3rd millennium BCE; recent excavations have uncovered a public eating area dating back about 4,700 years.","ar":"نافست لكش أُمّا وأور في الألف الثالث قبل الميلاد، وكشفت التنقيبات الحديثة عن مكان طعام عام يعود إلى نحو 4700 عام."}'::jsonb, 31.4136, 46.4061, true, null, '[]'::jsonb, null, null, 'Active excavation site — visits may require prior permission.', null, 'unknown', 1, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('76c47d59-e519-54df-b41e-f565dd862e67', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'girsu', '0197db69-38e3-54ef-88c9-3de576d6dac7', '{"en":"Girsu (Tello)","ar":"جرسو (تلّو)","ckb":"گیرسو","fr":"Girsu (Tello)","de":"Girsu (Tello)","es":"Girsu (Tello)"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"Religious capital of the state of Lagash, famous for the statues of Gudea.","ar":"العاصمة الدينية لدولة لكش، اشتهرت بتماثيل كوديا."}'::jsonb, '{"en":"Excavated from the 1870s; recent work has re-examined its temple of Ningirsu.","ar":"نُقّب فيها منذ سبعينيات القرن التاسع عشر، وأعادت أعمال حديثة دراسة معبد ننجرسو."}'::jsonb, 31.5486, 46.1747, true, null, '[]'::jsonb, null, null, 'Active excavation site — visits may require prior permission.', null, 'unknown', 1, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('b51cc7e8-d7dc-57da-8bbe-418c33090f62', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'central-marshes', '0197db69-38e3-54ef-88c9-3de576d6dac7', '{"en":"Mesopotamian Marshes (Central Marshes)","ar":"الأهوار (الأهوار الوسطى)","ckb":"زۆنگاوەکانی میزۆپۆتامیا","fr":"Marais de Mésopotamie","de":"Mesopotamische Sümpfe","es":"Marismas de Mesopotamia"}'::jsonb, '{"natural","cultural"}', '{"nature","culture"}', '{"en":"Wetlands of reed beds, water buffalo and mashoof boats, part of the UNESCO-listed Ahwar of Southern Iraq.","ar":"أراضٍ رطبة من القصب والجاموس والمشاحيف، جزء من موقع الأهوار المدرج في اليونسكو."}'::jsonb, '{"en":"Largely drained in the 1990s and partly re-flooded after 2003, the marshes are sensitive to drought and water levels vary greatly by year and season.","ar":"جُففت معظمها في التسعينيات وأعيد غمر أجزاء منها بعد 2003، وهي حساسة للجفاف وتتفاوت مناسيب المياه كثيراً بحسب السنة والموسم."}'::jsonb, 30.98, 47, true, '{"listing":"The Ahwar of Southern Iraq: Refuge of Biodiversity and the Relict Landscape of the Mesopotamian Cities","year":2016,"url":"https://whc.unesco.org/en/list/1481"}'::jsonb, '[]'::jsonb, null, null, 'Water levels and boat availability vary with drought conditions; confirm locally.', null, 'unknown', 4, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, true, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('0acde6df-077a-5c29-9f76-81c3e0d71921', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'al-chibayish', '0197db69-38e3-54ef-88c9-3de576d6dac7', '{"en":"Al-Chibayish","ar":"الجبايش","ckb":"چەبایش","fr":"Al-Chibayish","de":"Al-Chibayish","es":"Al-Chibayish"}'::jsonb, '{"natural","cultural"}', '{"nature","culture","food"}', '{"en":"Marsh town and the usual starting point for boat trips into the Central Marshes and visits to reed mudhifs.","ar":"بلدة في الأهوار ونقطة الانطلاق المعتادة لرحلات القوارب في الأهوار الوسطى وزيارة المضايف القصبية."}'::jsonb, '{"en":"Communities here maintain Marsh Arab traditions including reed architecture and buffalo herding.","ar":"تحافظ المجتمعات هنا على تقاليد عرب الأهوار ومنها العمارة القصبية وتربية الجاموس."}'::jsonb, 30.95, 47.03, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 4, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('2197f41a-f768-5ce8-a47c-2f2e37c9e280', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'uruk', '6655e779-48c0-530f-a6c6-9795b6c7e687', '{"en":"Uruk (Warka)","ar":"الوركاء (أوروك)","ckb":"ئوروک","fr":"Uruk","de":"Uruk","es":"Uruk"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"City of Gilgamesh and one of the first true cities, where early writing appeared.","ar":"مدينة جلجامش ومن أوائل المدن الحقيقية، حيث ظهرت الكتابة المبكرة."}'::jsonb, '{"en":"Uruk reached a population in the tens of thousands in the late 4th millennium BCE; the Eanna and Anu precincts remain visible as eroded mud-brick ruins.","ar":"بلغ عدد سكان أوروك عشرات الآلاف في أواخر الألف الرابع قبل الميلاد، ولا تزال منطقتا إينا وآنو ظاهرتين كأطلال طينية متآكلة."}'::jsonb, 31.324, 45.637, true, '{"listing":"The Ahwar of Southern Iraq: Refuge of Biodiversity and the Relict Landscape of the Mesopotamian Cities","year":2016,"url":"https://whc.unesco.org/en/list/1481"}'::jsonb, '[]'::jsonb, null, null, 'Remote desert site; local guide recommended.', null, 'unknown', 2, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('18ec2225-cb9f-50f3-bd1d-f3c9fde29bab', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'babylon-ancient-city', 'e260f45a-82f7-5224-8357-2e4e7016202c', '{"en":"Ancient Babylon","ar":"مدينة بابل الأثرية","ckb":"بابلی کۆن","fr":"Babylone antique","de":"Antikes Babylon","es":"Antigua Babilonia"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"The ruins of one of antiquity''s most famous cities, inscribed on the World Heritage List in 2019.","ar":"أطلال واحدة من أشهر مدن العالم القديم، أدرجت على قائمة التراث العالمي عام 2019."}'::jsonb, '{"en":"Capital of Hammurabi and Nebuchadnezzar II. Parts of the site were reconstructed in the 1980s, which visitors should distinguish from original remains.","ar":"عاصمة حمورابي ونبوخذنصر الثاني. أعيد بناء أجزاء من الموقع في الثمانينيات، وينبغي التمييز بينها وبين البقايا الأصلية."}'::jsonb, 32.5422, 44.4211, true, '{"listing":"Babylon","year":2019,"url":"https://whc.unesco.org/en/list/278"}'::jsonb, '[]'::jsonb, null, null, null, null, 'unknown', 3, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, true, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('c83ad70c-19b7-5f02-bacf-88e8c3b9daaa', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'ishtar-gate-area', 'e260f45a-82f7-5224-8357-2e4e7016202c', '{"en":"Ishtar Gate archaeological area","ar":"منطقة بوابة عشتار","ckb":"ناوچەی دەروازەی عەشتار","fr":"Zone de la porte d''Ishtar","de":"Bereich des Ischtar-Tors","es":"Zona de la Puerta de Ishtar"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"The excavated foundations of the Ishtar Gate with original relief bricks of bulls and dragons; a replica gate stands at the entrance.","ar":"أسس بوابة عشتار المنقّبة مع آجرّ أصلي بنقوش الثيران والتنانين، وتقف نسخة مقلدة من البوابة عند المدخل."}'::jsonb, '{"en":"The glazed upper gate was removed in the early 20th century and is reconstructed in Berlin''s Pergamon Museum; the lower foundations remain in situ.","ar":"نُقلت البوابة المزججة العليا في أوائل القرن العشرين وأعيد بناؤها في متحف بيرغامون ببرلين، وبقيت الأسس السفلى في مكانها."}'::jsonb, 32.5436, 44.421, true, '{"listing":"Babylon","year":2019,"url":"https://whc.unesco.org/en/list/278"}'::jsonb, '[]'::jsonb, null, null, null, null, 'unknown', 1, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('f3475da7-d63f-5ea1-aa68-d803909ca269', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'lion-of-babylon', 'e260f45a-82f7-5224-8357-2e4e7016202c', '{"en":"Lion of Babylon","ar":"أسد بابل","ckb":"شێری بابل","fr":"Lion de Babylone","de":"Löwe von Babylon","es":"León de Babilonia"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"A large basalt statue of a lion standing over a human figure, a symbol of Babylon.","ar":"تمثال كبير من البازلت لأسد يعلو شخصاً، وهو رمز لبابل."}'::jsonb, '{"en":"Found in 1876; its date and origin are debated by scholars.","ar":"عُثر عليه عام 1876، ويختلف الباحثون في تاريخه وأصله."}'::jsonb, 32.545, 44.4217, true, '{"listing":"Babylon","year":2019,"url":"https://whc.unesco.org/en/list/278"}'::jsonb, '[]'::jsonb, null, null, null, null, 'unknown', 0.5, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('ca267bf7-ddc3-5c85-9013-1393bcaacc9d', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'processional-way', 'e260f45a-82f7-5224-8357-2e4e7016202c', '{"en":"Processional Way","ar":"شارع الموكب","ckb":"ڕێگای کاروان","fr":"Voie processionnelle","de":"Prozessionsstraße","es":"Vía Procesional"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"The ceremonial road that led through the Ishtar Gate during New Year (Akitu) festivals.","ar":"الطريق الاحتفالي الذي كان يمر عبر بوابة عشتار خلال احتفالات رأس السنة (أكيتو)."}'::jsonb, '{"en":"Built under Nebuchadnezzar II; sections of the original paving and walls survive.","ar":"شُيّد في عهد نبوخذنصر الثاني، ولا تزال أجزاء من رصفه وجدرانه الأصلية قائمة."}'::jsonb, 32.544, 44.4212, true, '{"listing":"Babylon","year":2019,"url":"https://whc.unesco.org/en/list/278"}'::jsonb, '[]'::jsonb, null, null, null, null, 'unknown', 0.5, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('8826560c-34f3-5582-8959-96d0b0be4b7a', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'imam-ali-shrine', 'bc041521-0cc8-5b77-87ef-544de264c19f', '{"en":"Imam Ali Shrine","ar":"العتبة العلوية المقدسة (مرقد الإمام علي)","ckb":"مەرقەدی ئیمام عەلی","fr":"Mausolée de l''imam Ali","de":"Imam-Ali-Schrein","es":"Santuario del Imán Alí"}'::jsonb, '{"religious"}', '{"religious","culture","history"}', '{"en":"The golden-domed shrine of Imam Ali ibn Abi Talib, one of the most visited pilgrimage sites in the world.","ar":"مرقد الإمام علي بن أبي طالب ذو القبة الذهبية، من أكثر مواقع الزيارة استقبالاً للزوار في العالم."}'::jsonb, '{"en":"The shrine has been rebuilt and expanded many times; the current structure largely dates from the Safavid era with major modern extensions.","ar":"أعيد بناء المرقد وتوسيعه مرات عديدة، ويعود معظم البناء الحالي إلى العهد الصفوي مع توسعات حديثة كبيرة."}'::jsonb, 31.9961, 44.3143, true, null, '[]'::jsonb, null, null, 'Active place of worship: modest dress is required (women typically need to cover hair; an abaya may be required at shrine entrances). Security checks are standard; cameras and bags may be restricted. Non-Muslim access rules vary — confirm locally.', null, 'unknown', 2, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, true, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('c82b1b5f-9ce1-5311-84fd-50c30ea28c69', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'wadi-al-salam', 'bc041521-0cc8-5b77-87ef-544de264c19f', '{"en":"Wadi al-Salam Cemetery","ar":"مقبرة وادي السلام","ckb":"گۆڕستانی وادی سەلام","fr":"Cimetière de Wadi al-Salam","de":"Friedhof Wadi as-Salam","es":"Cementerio de Wadi al-Salam"}'::jsonb, '{"religious","historic_city"}', '{"religious","history"}', '{"en":"One of the largest cemeteries in the world, adjoining the old city of Najaf.","ar":"من أكبر المقابر في العالم، ملاصقة للمدينة القديمة في النجف."}'::jsonb, '{"en":"Used for burials for well over a thousand years; it contains the tombs of prophets venerated in Islamic tradition.","ar":"تُستخدم للدفن منذ أكثر من ألف عام، وفيها مراقد أنبياء يجلّهم التقليد الإسلامي."}'::jsonb, 32.01, 44.32, true, null, '[]'::jsonb, null, null, 'Active cemetery — behave respectfully; photography of funerals is inappropriate.', null, 'unknown', 1, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('b896ed87-d233-5255-ba1f-4d3b63e8a98d', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'great-mosque-of-kufa', 'bc041521-0cc8-5b77-87ef-544de264c19f', '{"en":"Great Mosque of Kufa","ar":"مسجد الكوفة","ckb":"مزگەوتی گەورەی کووفە","fr":"Grande mosquée de Koufa","de":"Große Moschee von Kufa","es":"Gran Mezquita de Kufa"}'::jsonb, '{"religious","historic_city"}', '{"religious","history"}', '{"en":"One of the earliest mosques in Islam, where Imam Ali was struck in 661 CE.","ar":"من أقدم المساجد في الإسلام، وفيه ضُرب الإمام علي عام 661م."}'::jsonb, '{"en":"Built in the 7th century CE when Kufa was founded as a garrison city; it has been extensively rebuilt.","ar":"بُني في القرن السابع الميلادي عند تأسيس الكوفة معسكراً، وأعيد بناؤه مرات كثيرة."}'::jsonb, 32.0287, 44.4007, true, null, '[]'::jsonb, null, null, 'Active place of worship: modest dress is required (women typically need to cover hair; an abaya may be required at shrine entrances). Security checks are standard; cameras and bags may be restricted. Non-Muslim access rules vary — confirm locally.', null, 'unknown', 1.5, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('e2437c9f-2f09-5515-b428-39fb7a324acd', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'dar-al-imara', 'bc041521-0cc8-5b77-87ef-544de264c19f', '{"en":"Dar al-Imara (Kufa)","ar":"دار الإمارة في الكوفة","ckb":"دارولئیمارە","fr":"Dar al-Imara","de":"Dar al-Imara","es":"Dar al-Imara"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"Excavated foundations of the governor''s palace beside the Kufa Mosque.","ar":"أسس قصر الإمارة المنقّبة بجوار مسجد الكوفة."}'::jsonb, '{"en":"The early Islamic seat of government in Kufa; the visible remains are low walls revealed by excavation.","ar":"مقر الحكم في الكوفة في صدر الإسلام، وما يظهر منه جدران منخفضة كشفتها التنقيبات."}'::jsonb, 32.0283, 44.4013, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 0.5, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('8031e389-2c13-53d3-ae4b-37ed46e4e89b', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'imam-hussein-shrine', '743750bf-c400-5645-94bc-4e3306ab7c0d', '{"en":"Imam Hussein Shrine","ar":"العتبة الحسينية المقدسة","ckb":"مەرقەدی ئیمام حوسێن","fr":"Mausolée de l''imam Hussein","de":"Imam-Hussein-Schrein","es":"Santuario del Imán Husein"}'::jsonb, '{"religious"}', '{"religious","culture","history"}', '{"en":"Shrine of Imam Hussein ibn Ali, centre of the Ashura and Arbaeen pilgrimages.","ar":"مرقد الإمام الحسين بن علي، ومحور زيارتي عاشوراء والأربعين."}'::jsonb, '{"en":"Built over the burial site of Imam Hussein, killed at the Battle of Karbala in 680 CE.","ar":"شُيّد فوق موضع دفن الإمام الحسين الذي استشهد في واقعة الطف عام 680م."}'::jsonb, 32.6164, 44.0324, true, null, '[]'::jsonb, null, null, 'Active place of worship: modest dress is required (women typically need to cover hair; an abaya may be required at shrine entrances). Security checks are standard; cameras and bags may be restricted. Non-Muslim access rules vary — confirm locally.', null, 'unknown', 2, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, true, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('a41a3976-e3cb-5950-90fe-c9ca43fa6688', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'al-abbas-shrine', '743750bf-c400-5645-94bc-4e3306ab7c0d', '{"en":"Al-Abbas Shrine","ar":"العتبة العباسية المقدسة","ckb":"مەرقەدی عەباس","fr":"Mausolée d''al-Abbas","de":"Al-Abbas-Schrein","es":"Santuario de al-Abbas"}'::jsonb, '{"religious"}', '{"religious","culture"}', '{"en":"Shrine of Al-Abbas ibn Ali, facing the Imam Hussein Shrine across the Bayn al-Haramayn plaza.","ar":"مرقد أبي الفضل العباس بن علي، مقابل مرقد الإمام الحسين عبر ساحة ما بين الحرمين."}'::jsonb, '{"en":"Al-Abbas was Imam Hussein''s half-brother and standard-bearer at Karbala.","ar":"العباس أخو الإمام الحسين وحامل لوائه في كربلاء."}'::jsonb, 32.6158, 44.0352, true, null, '[]'::jsonb, null, null, 'Active place of worship: modest dress is required (women typically need to cover hair; an abaya may be required at shrine entrances). Security checks are standard; cameras and bags may be restricted. Non-Muslim access rules vary — confirm locally.', null, 'unknown', 1.5, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('fa579c22-50bf-5a8c-b836-1edefb898ae4', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'al-ukhaidir', '743750bf-c400-5645-94bc-4e3306ab7c0d', '{"en":"Al-Ukhaidir Fortress","ar":"حصن الأخيضر","ckb":"قەڵای ئوخەیدر","fr":"Forteresse d''Ukhaidir","de":"Festung al-Uchaidir","es":"Fortaleza de Ujaidir"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"A massive early Abbasid desert palace-fortress with tall walls, vaults and courtyards.","ar":"قصر-حصن صحراوي ضخم من أوائل العصر العباسي بأسوار عالية وأقبية وأفنية."}'::jsonb, '{"en":"Generally dated to around 775 CE; an important example of early Islamic architecture.","ar":"يؤرّخ عموماً بنحو عام 775م، وهو نموذج مهم للعمارة الإسلامية المبكرة."}'::jsonb, 32.4388, 43.6017, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 1.5, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('8db2d4ae-e79d-5a68-afaa-d1aaf71a1010', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'lake-razzaza', '743750bf-c400-5645-94bc-4e3306ab7c0d', '{"en":"Lake Razzaza","ar":"بحيرة الرزازة","ckb":"دەریاچەی ڕەززازە","fr":"Lac Razzaza","de":"Razzaza-See","es":"Lago Razzaza"}'::jsonb, '{"natural"}', '{"nature"}', '{"en":"A large desert lake west of Karbala whose water level has declined significantly in recent years.","ar":"بحيرة صحراوية كبيرة غرب كربلاء تراجع منسوب مياهها كثيراً في السنوات الأخيرة."}'::jsonb, '{"en":"Formed as part of a water-management depression; it is an important but stressed wetland for birds.","ar":"تكوّنت ضمن منخفض لتصريف المياه، وهي أرض رطبة مهمة للطيور لكنها تعاني ضغطاً بيئياً."}'::jsonb, 32.7, 43.65, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 2, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('06dabe90-a1fd-51f6-aaa3-ad2459db989e', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'erbil-citadel', 'dd6319b9-a963-5cf3-bdfe-4935bf5171db', '{"en":"Erbil Citadel","ar":"قلعة أربيل","ckb":"قەڵای هەولێر","fr":"Citadelle d''Erbil","de":"Zitadelle von Erbil","es":"Ciudadela de Erbil"}'::jsonb, '{"historic_city","archaeological"}', '{"history","archaeology","culture"}', '{"en":"A fortified settlement atop a tell in the heart of Erbil, inscribed on the World Heritage List in 2014.","ar":"مستوطنة محصنة فوق تل في قلب أربيل، أدرجت على قائمة التراث العالمي عام 2014."}'::jsonb, '{"en":"The mound has been occupied for millennia; the citadel houses a textile museum and is undergoing long-term restoration.","ar":"سُكن التل منذ آلاف السنين، وتضم القلعة متحفاً للمنسوجات وتخضع لأعمال ترميم طويلة الأمد."}'::jsonb, 36.1912, 44.0092, true, '{"listing":"Erbil Citadel","year":2014,"url":"https://whc.unesco.org/en/list/1437"}'::jsonb, '[]'::jsonb, null, null, null, null, 'unknown', 2, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, true, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('2cd98d26-3463-5698-a9ee-d242a7dd7a20', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'sami-abdulrahman-park', 'dd6319b9-a963-5cf3-bdfe-4935bf5171db', '{"en":"Sami Abdulrahman Park","ar":"متنزه سامي عبد الرحمن","ckb":"پارکی سامی عەبدولڕەحمان","fr":"Parc Sami Abdulrahman","de":"Sami-Abdulrahman-Park","es":"Parque Sami Abdulrahman"}'::jsonb, '{"park"}', '{"nature","entertainment"}', '{"en":"Erbil''s largest public park, with lakes, walking paths and family areas.","ar":"أكبر حديقة عامة في أربيل، فيها بحيرات وممرات للمشي ومناطق عائلية."}'::jsonb, '{"en":"Built on the site of a former military base and named after the Kurdish politician Sami Abdulrahman.","ar":"أنشئت على موقع قاعدة عسكرية سابقة وسُمّيت باسم السياسي الكردي سامي عبد الرحمن."}'::jsonb, 36.198, 43.989, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 2, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('4c29c415-03db-5d7f-9ef2-1e69a3088837', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'amedi', '9658bce8-6122-589a-a7c9-030c863c62d2', '{"en":"Amedi (Amadiya)","ar":"العمادية","ckb":"ئامێدی","fr":"Amadiya","de":"Amadiya","es":"Amadiya"}'::jsonb, '{"historic_city","natural"}', '{"history","nature","culture"}', '{"en":"A historic town perched on a flat-topped mountain, with the old Bab Zebar gate and dramatic valley views.","ar":"بلدة تاريخية فوق جبل مسطح القمة، فيها باب زيبار القديم وإطلالات خلابة على الوادي."}'::jsonb, '{"en":"Amedi was the seat of the Bahdinan emirate and has been home to Muslim, Christian and Jewish communities.","ar":"كانت مقر إمارة بهدينان وسكنتها مجتمعات مسلمة ومسيحية ويهودية."}'::jsonb, 37.0925, 43.487, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 3, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('3a2684da-e52a-5c24-8a72-4b8e6004e66c', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'lalish', '9658bce8-6122-589a-a7c9-030c863c62d2', '{"en":"Lalish","ar":"لالش","ckb":"لالش","fr":"Lalish","de":"Lalisch","es":"Lalish"}'::jsonb, '{"religious"}', '{"religious","culture"}', '{"en":"The sacred valley and temple of Sheikh Adi, the holiest place for Yazidis.","ar":"الوادي المقدس ومعبد الشيخ عدي، أقدس مكان لدى الإيزيديين."}'::jsonb, '{"en":"Pilgrims gather here especially for the autumn Jema''iyye feast. Visitors should follow the guidance of temple custodians.","ar":"يجتمع الحجاج هنا خصوصاً في عيد الجماعية الخريفي، وعلى الزوار اتباع إرشادات سدنة المعبد."}'::jsonb, 36.766, 43.299, true, null, '[]'::jsonb, null, null, 'Holiest site of the Yazidi faith. Visitors customarily remove shoes within the sanctuary area; ask before photographing people.', null, 'unknown', 2, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('e9fc82ce-a0e6-5bc4-9405-3f5a9e6ea34c', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'sarsang', '9658bce8-6122-589a-a7c9-030c863c62d2', '{"en":"Sarsang","ar":"سرسنك","ckb":"سەرسنگ","fr":"Sarsang","de":"Sarsang","es":"Sarsang"}'::jsonb, '{"natural"}', '{"nature","entertainment"}', '{"en":"A mountain resort area popular in summer for its cooler climate, springs and valleys.","ar":"منطقة مصايف جبلية مقصودة صيفاً لاعتدال مناخها وينابيعها وأوديتها."}'::jsonb, '{"en":"A traditional summer retreat for families from the plains of Iraq.","ar":"مصيف تقليدي للعائلات القادمة من سهول العراق."}'::jsonb, 37.05, 43.345, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 3, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('6e10973f-59bf-580d-bdf7-f4fbce3b3a25', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'sulaymaniyah-museum', '5fb82d98-8dc3-5106-96fe-be9cedf16bce', '{"en":"Sulaymaniyah Museum","ar":"متحف السليمانية","ckb":"مۆزەخانەی سلێمانی","fr":"Musée de Souleimaniye","de":"Museum Sulaimaniyya","es":"Museo de Solimania"}'::jsonb, '{"museum"}', '{"history","archaeology","culture"}', '{"en":"The second-largest museum in Iraq, with prehistoric to Islamic-era collections.","ar":"ثاني أكبر متحف في العراق، يضم مجموعات من عصور ما قبل التاريخ حتى العصر الإسلامي."}'::jsonb, '{"en":"Founded in 1961, it holds many objects from excavations in the Kurdistan Region.","ar":"تأسس عام 1961 ويضم قطعاً كثيرة من تنقيبات إقليم كردستان."}'::jsonb, 35.56, 45.433, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 2, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('db8e79a8-017a-5fd2-91c1-6f8c355b396a', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'lake-dukan', '5fb82d98-8dc3-5106-96fe-be9cedf16bce', '{"en":"Lake Dukan","ar":"بحيرة دوكان","ckb":"دەریاچەی دوکان","fr":"Lac de Doukan","de":"Dukan-See","es":"Lago Dukan"}'::jsonb, '{"natural"}', '{"nature","entertainment"}', '{"en":"A large reservoir on the Little Zab surrounded by hills, popular for weekend outings.","ar":"خزان مائي كبير على الزاب الصغير تحيط به التلال، مقصد شائع لنزهات نهاية الأسبوع."}'::jsonb, '{"en":"Created by the Dukan Dam, completed in 1959.","ar":"تكوّنت بإنشاء سد دوكان الذي اكتمل عام 1959."}'::jsonb, 35.95, 44.95, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 4, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('4013b958-436e-5a46-86cb-8174049464ae', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'ahmad-awa', '5fb82d98-8dc3-5106-96fe-be9cedf16bce', '{"en":"Ahmad Awa Waterfall","ar":"شلال أحمد آوا","ckb":"تاڤگەی ئەحمەد ئاوا","fr":"Cascade d''Ahmad Awa","de":"Ahmad-Awa-Wasserfall","es":"Cascada de Ahmad Awa"}'::jsonb, '{"natural"}', '{"nature"}', '{"en":"A mountain waterfall and gorge near the Iranian border, a popular hiking spot.","ar":"شلال وأخدود جبلي قرب الحدود الإيرانية، مقصد شائع للمشي."}'::jsonb, '{"en":"Located in the Hawraman area; access roads are close to the border.","ar":"يقع في منطقة هورامان، وطرق الوصول قريبة من الحدود."}'::jsonb, 35.297, 46.047, true, null, '[]'::jsonb, null, null, 'Close to the international border — check current advisories before visiting.', null, 'unknown', 3, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('30db46b7-4bbb-515d-b28e-bc7b6b324c65', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'hatra', '8b5f9dd4-3402-5aaa-9cc2-8a58611e7112', '{"en":"Hatra","ar":"الحضر","ckb":"هەترا","fr":"Hatra","de":"Hatra","es":"Hatra"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"A fortified Parthian-era city with temples blending Hellenistic, Roman and Arab elements.","ar":"مدينة محصنة من العهد الفرثي، معابدها تمزج بين العناصر الهلنستية والرومانية والعربية."}'::jsonb, '{"en":"Hatra resisted Roman sieges in the 2nd century CE. The site was damaged in 2015; it is on UNESCO''s List of World Heritage in Danger.","ar":"صمدت الحضر أمام الحصار الروماني في القرن الثاني الميلادي، وتضررت عام 2015، وهي مدرجة على قائمة التراث العالمي المعرض للخطر."}'::jsonb, 35.5875, 42.7183, true, '{"listing":"Hatra","year":1985,"url":"https://whc.unesco.org/en/list/277"}'::jsonb, '[]'::jsonb, null, null, 'Access may require permits; check current status before planning.', null, 'unknown', 2, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, true, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('511263da-cd17-5698-8325-10ae917301b0', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'nimrud', '8b5f9dd4-3402-5aaa-9cc2-8a58611e7112', '{"en":"Nimrud (Kalhu)","ar":"النمرود (كالخو)","ckb":"نەمروود","fr":"Nimroud","de":"Nimrud","es":"Nimrud"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"Assyrian royal capital known for its palace reliefs and ivories.","ar":"عاصمة آشورية ملكية اشتهرت بمنحوتات قصورها وعاجياتها."}'::jsonb, '{"en":"Capital under Ashurnasirpal II (9th century BCE). Much of the site was deliberately destroyed in 2015; restoration and documentation are ongoing.","ar":"كانت عاصمة في عهد آشورناصربال الثاني (القرن التاسع ق.م)، ودُمّر جزء كبير منها عمداً عام 2015، وتجري أعمال توثيق وترميم."}'::jsonb, 36.0986, 43.3289, true, null, '[]'::jsonb, null, null, 'Access may require permits; check current status before planning.', null, 'unknown', 1.5, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('5079876b-8307-52dd-a4b3-2baf1d70b275', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'nineveh-ancient-city', '8b5f9dd4-3402-5aaa-9cc2-8a58611e7112', '{"en":"Ancient Nineveh","ar":"نينوى الأثرية","ckb":"نەینەوای کۆن","fr":"Ninive antique","de":"Antikes Ninive","es":"Antigua Nínive"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"The ruins of the Assyrian capital on the east bank of the Tigris in Mosul, with reconstructed city gates.","ar":"أطلال العاصمة الآشورية على الضفة الشرقية لدجلة في الموصل، مع بوابات مدينة معاد بناؤها."}'::jsonb, '{"en":"Capital of Sennacherib and Ashurbanipal, whose library of clay tablets is one of the great discoveries of archaeology.","ar":"عاصمة سنحاريب وآشوربانيبال الذي تعدّ مكتبته من الألواح الطينية من أعظم الاكتشافات الأثرية."}'::jsonb, 36.3594, 43.1528, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 2, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('91173eeb-c605-5179-afde-ddc7bfdc0731', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'old-mosul', '8b5f9dd4-3402-5aaa-9cc2-8a58611e7112', '{"en":"Old City of Mosul","ar":"الموصل القديمة","ckb":"مووسڵی کۆن","fr":"Vieille ville de Mossoul","de":"Altstadt von Mossul","es":"Ciudad vieja de Mosul"}'::jsonb, '{"historic_city","religious"}', '{"history","culture","religious"}', '{"en":"The historic city on the west bank of the Tigris, including the Al-Nuri Mosque and its rebuilt al-Hadba minaret, and historic churches.","ar":"المدينة التاريخية على الضفة الغربية لدجلة، ومنها جامع النوري ومئذنة الحدباء المعاد بناؤها والكنائس التاريخية."}'::jsonb, '{"en":"Heavily damaged in 2017, the old city has been the focus of large reconstruction projects, including UNESCO''s ''Revive the Spirit of Mosul''.","ar":"تعرضت لدمار كبير عام 2017 وكانت محور مشاريع إعادة إعمار كبرى منها مبادرة اليونسكو «إحياء روح الموصل»."}'::jsonb, 36.3412, 43.129, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 3, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('b7e8e06f-c4f4-5b35-bad0-66538fab979d', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'great-mosque-of-samarra', '03793466-c810-5844-8e51-b11a3c9094ec', '{"en":"Great Mosque of Samarra","ar":"الجامع الكبير في سامراء","ckb":"مزگەوتی گەورەی سامەڕا","fr":"Grande mosquée de Samarra","de":"Große Moschee von Samarra","es":"Gran Mezquita de Samarra"}'::jsonb, '{"archaeological","religious"}', '{"archaeology","history","religious"}', '{"en":"The vast 9th-century Abbasid mosque enclosure, once the largest mosque in the world.","ar":"حرم الجامع العباسي الضخم من القرن التاسع، وكان يوماً أكبر مسجد في العالم."}'::jsonb, '{"en":"Built by Caliph al-Mutawakkil around 848–852 CE; its outer walls survive.","ar":"بناه الخليفة المتوكل نحو 848–852م، ولا تزال أسواره الخارجية قائمة."}'::jsonb, 34.2059, 43.8789, true, '{"listing":"Samarra Archaeological City","year":2007,"url":"https://whc.unesco.org/en/list/276"}'::jsonb, '[]'::jsonb, null, null, null, null, 'unknown', 1.5, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, true, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('9ec1bb6c-034e-5b9a-ac11-a5f8670a66f2', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'malwiya-minaret', '03793466-c810-5844-8e51-b11a3c9094ec', '{"en":"Malwiya Minaret","ar":"المئذنة الملوية","ckb":"منارەی مەلویە","fr":"Minaret Malwiya","de":"Malwiya-Minarett","es":"Minarete Malwiya"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"The famous spiral minaret of the Great Mosque of Samarra, about 52 metres high.","ar":"المئذنة الحلزونية الشهيرة للجامع الكبير في سامراء، بارتفاع نحو 52 متراً."}'::jsonb, '{"en":"Its spiral ramp design is unique in Islamic architecture. Climbing it may be restricted — confirm on site.","ar":"تصميمها الحلزوني فريد في العمارة الإسلامية. قد يكون الصعود مقيداً — تأكد في الموقع."}'::jsonb, 34.2072, 43.8796, true, '{"listing":"Samarra Archaeological City","year":2007,"url":"https://whc.unesco.org/en/list/276"}'::jsonb, '[]'::jsonb, null, null, 'Climbing may be restricted; no guard rails on the ramp.', null, 'unknown', 1, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('4d8d92f8-696f-55f2-8873-01fc2a0a1a9a', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'ashur', '03793466-c810-5844-8e51-b11a3c9094ec', '{"en":"Ashur (Qal''at Sherqat)","ar":"آشور (قلعة الشرقاط)","ckb":"ئاشوور","fr":"Assour","de":"Assur","es":"Asur"}'::jsonb, '{"archaeological"}', '{"archaeology","history"}', '{"en":"The first capital and religious centre of Assyria, on the Tigris.","ar":"العاصمة الأولى والمركز الديني لآشور، على نهر دجلة."}'::jsonb, '{"en":"Inscribed in 2003 and placed on the List of World Heritage in Danger the same year.","ar":"أدرجت عام 2003 ووضعت في العام نفسه على قائمة التراث العالمي المعرض للخطر."}'::jsonb, 35.4567, 43.2622, true, '{"listing":"Ashur (Qal''at Sherqat)","year":2003,"url":"https://whc.unesco.org/en/list/1130"}'::jsonb, '[]'::jsonb, null, null, 'Access may require permits; check current status before planning.', null, 'unknown', 1.5, '{"7536ffa9-94de-5b03-81fc-2fb5a6e6ba4b","71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('7321ec83-2e25-57fd-88a7-33a7d75ae275', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'kirkuk-citadel', '2e3ab8fe-1de7-5b44-93c9-ea0a46a0c15c', '{"en":"Kirkuk Citadel","ar":"قلعة كركوك","ckb":"قەڵای کەرکووک","fr":"Citadelle de Kirkouk","de":"Zitadelle von Kirkuk","es":"Ciudadela de Kirkuk"}'::jsonb, '{"historic_city","archaeological"}', '{"history","archaeology"}', '{"en":"A historic mound above the Khasa river with old houses, mosques and the tomb traditionally associated with the Prophet Daniel.","ar":"تل تاريخي فوق نهر الخاصة فيه بيوت قديمة ومساجد ومرقد ينسب تقليدياً إلى النبي دانيال."}'::jsonb, '{"en":"Occupied since ancient times; restoration has been undertaken in parts of the citadel.","ar":"مأهولة منذ العصور القديمة، وأجريت أعمال ترميم في أجزاء من القلعة."}'::jsonb, 35.4688, 44.3956, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 1.5, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('693a44b0-c11d-5c06-be27-2174682291de', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'shatt-al-arab', '0377e504-cc2d-5112-9011-c9a08cee2c1a', '{"en":"Shatt al-Arab","ar":"شط العرب","ckb":"شەتولعەرەب","fr":"Chatt-el-Arab","de":"Schatt al-Arab","es":"Shatt al-Arab"}'::jsonb, '{"natural"}', '{"nature","culture"}', '{"en":"The river formed by the Tigris and Euphrates, lined with date-palm groves; boat rides depart from Basra.","ar":"النهر المتكون من التقاء دجلة والفرات، تحفّه بساتين النخيل، وتنطلق جولات القوارب من البصرة."}'::jsonb, '{"en":"Historically a vital trade artery linking Basra to the Gulf.","ar":"شريان تجاري حيوي تاريخياً يربط البصرة بالخليج."}'::jsonb, 30.53, 47.83, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 2, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
insert into public.tourist_sites (id, created_at, updated_at, published, slug, governorate_id, name, categories, interests, summary, history, lat, lng, coordinates_approximate, unesco, images, opening_hours, entrance_fee, visitor_restrictions, accessibility, access_status, recommended_visit_hours, source_ids, verification_status, last_verified, featured, is_demo) values ('57d60a8e-1bf1-586c-8b9f-eb4256663064', '2026-11-19T00:00:00.000Z', '2026-11-19T00:00:00.000Z', true, 'basra-corniche', '0377e504-cc2d-5112-9011-c9a08cee2c1a', '{"en":"Basra Corniche","ar":"كورنيش البصرة","ckb":"کۆرنیشی بەسرە","fr":"Corniche de Bassorah","de":"Corniche von Basra","es":"Corniche de Basora"}'::jsonb, '{"park","cultural"}', '{"entertainment","food","culture"}', '{"en":"A riverside promenade along the Shatt al-Arab, lively in the evenings, with statues of Iraqi poets.","ar":"ممشى نهري على شط العرب يعجّ بالحياة مساءً، وفيه تماثيل لشعراء عراقيين."}'::jsonb, '{"en":"Features the well-known statue of the poet Badr Shakir al-Sayyab.","ar":"يضم تمثال الشاعر بدر شاكر السياب المعروف."}'::jsonb, 30.512, 47.827, true, null, '[]'::jsonb, null, null, null, null, 'unknown', 2, '{"71010673-1fef-53d1-b1e6-63e772e06c19"}', 'unverified', null, false, false) on conflict (id) do nothing;
